package com.own.order.domain;
import java.math.BigDecimal; import javax.persistence.*;
@Entity @Table(name="ord_after_sale_item") public class AfterSaleItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="after_sale_no",nullable=false,length=64) private String afterSaleNo; @Column(name="order_item_id",nullable=false) private Long orderItemId; @Column(name="product_id",nullable=false) private Long productId; @Column(nullable=false) private Integer quantity; @Column(name="refund_amount",nullable=false,precision=19,scale=2) private BigDecimal refundAmount; protected AfterSaleItem(){} public AfterSaleItem(String saleNo,OrderItem item,Integer quantity,BigDecimal refundAmount){this.afterSaleNo=saleNo;this.orderItemId=item.getId();this.productId=item.getProductId();this.quantity=quantity;this.refundAmount=refundAmount;} public Long getOrderItemId(){return orderItemId;} public Long getProductId(){return productId;} public Integer getQuantity(){return quantity;} public BigDecimal getRefundAmount(){return refundAmount;} }
